-- VERSION-MONOTONIC-TUPLE-1   *** PROPOSED - NOT YET APPLIED TO PRODUCTION (unless the deploy notes say otherwise) ***
-- Target DB: qnfo-audit (35e2e573-92f3-46ac-83c6-22f6429fc5e5), table deployment_history.
--
-- Replaces trigger deployment_history_version_monotonic_ins (issue #1451). The production trigger
-- compares versions as `CAST(replace(core_version,'.','') AS INTEGER)`: 2.37.32 -> 23732 but
-- 2.38.2 -> 2382, so it aborts legitimate upgrades ("VERSION-MONOTONIC-1: version regresses ...")
-- and accepts real regressions (2.9.99 after 2.10.0). Measured 2026-09-30: raw_put.py got
-- HTTP 400 from the ledger for qnfo-ops 2.38.2 and deployment_history has no qnfo-ops row after
-- 2.37.32 although 2.38.1 and 2.38.2 were deployed => DEPLOY-UNLOGGED-MUTATION alerts.
--
-- The replacement compares (major, minor, patch) as integers: major*1e8 + minor*1e4 + patch.
-- Same WHEN conditions otherwise: skipped for empty/NULL/non-version ids, for notes containing
-- ROLLBACK-OK, per resource_name, equal versions allowed, same abort message.
-- Test: python3 scripts/test_version_monotonic_trigger.py  (production text vs this, 12 cases:
-- production wrong on 4, this wrong on 0). The test asserts this file contains the generated text.
--
-- APPLY (atomic enough for D1: two statements, the guard is off only between them):
--   DROP TRIGGER deployment_history_version_monotonic_ins;
--   <the CREATE TRIGGER below>
-- VERIFY:  SELECT name FROM sqlite_master WHERE type='trigger' AND name='deployment_history_version_monotonic_ins';
--          then a deploy of a 2.38.x version should write a ledger row (raw_put.py: "DEPLOY-LEDGER: HTTP 200").
-- ROLLBACK: DROP TRIGGER deployment_history_version_monotonic_ins; and re-create the previous text,
--           which is embedded as OLD in scripts/test_version_monotonic_trigger.py.

DROP TRIGGER IF EXISTS deployment_history_version_monotonic_ins;

case                                                       want   OLD(prod)  NEW     
REAL LEDGER: 2.38.2 after 2.37.32 (upgrade)                ACCEPT REJECT     <-WRONG ACCEPT  
REAL LEDGER: 2.38.1 after 2.37.32 (upgrade)                ACCEPT REJECT     <-WRONG ACCEPT  
true regression 2.37.31 after 2.37.32                      REJECT REJECT     REJECT  
true regression 2.37.31 after 2.38.2                       REJECT REJECT     REJECT  
dot-strip accepts a regression: 2.9.99 after 2.10.0        REJECT ACCEPT     <-WRONG REJECT  
dot-strip rejects an upgrade: 2.10.0 after 2.9.30          ACCEPT REJECT     <-WRONG ACCEPT  
same version redeploy                                      ACCEPT ACCEPT     ACCEPT  
intentional rollback with ROLLBACK-OK                      ACCEPT ACCEPT     ACCEPT  
other resource is independent                              ACCEPT ACCEPT     ACCEPT  
non-version id (sha) ignored                               ACCEPT ACCEPT     ACCEPT  
two-segment version 1.5 after 1.10                         REJECT REJECT     REJECT  
first row for a resource                                   ACCEPT ACCEPT     ACCEPT  
CREATE TRIGGER deployment_history_version_monotonic_ins BEFORE INSERT ON deployment_history FOR EACH ROW WHEN NEW.version_id IS NOT NULL AND NEW.version_id != '' AND instr(COALESCE(NEW.notes,''),'ROLLBACK-OK') = 0 AND (substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END) GLOB '[0-9]*.[0-9]*' AND length(replace(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),'.','')) <= 6) AND (CAST(substr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),1,instr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),'.')-1) AS INTEGER)*100000000 + CAST(CASE WHEN instr(substr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),instr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),'.')+1),'.')>0 THEN substr(substr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),instr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),'.')+1),1,instr(substr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),instr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),'.')+1),'.')-1) ELSE substr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),instr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),'.')+1) END AS INTEGER)*10000 + CASE WHEN instr(substr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),instr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),'.')+1),'.')>0 THEN CAST(substr(substr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),instr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),'.')+1),instr(substr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),instr(substr(NEW.version_id,1,CASE WHEN instr(NEW.version_id,'-')>0 THEN instr(NEW.version_id,'-')-1 ELSE length(NEW.version_id) END),'.')+1),'.')+1) AS INTEGER) ELSE 0 END) < COALESCE((SELECT MAX((CAST(substr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),1,instr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),'.')-1) AS INTEGER)*100000000 + CAST(CASE WHEN instr(substr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),instr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),'.')+1),'.')>0 THEN substr(substr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),instr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),'.')+1),1,instr(substr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),instr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),'.')+1),'.')-1) ELSE substr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),instr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),'.')+1) END AS INTEGER)*10000 + CASE WHEN instr(substr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),instr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),'.')+1),'.')>0 THEN CAST(substr(substr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),instr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),'.')+1),instr(substr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),instr(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),'.')+1),'.')+1) AS INTEGER) ELSE 0 END)) FROM deployment_history WHERE resource_name = NEW.resource_name AND (substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END) GLOB '[0-9]*.[0-9]*' AND length(replace(substr(version_id,1,CASE WHEN instr(version_id,'-')>0 THEN instr(version_id,'-')-1 ELSE length(version_id) END),'.','')) <= 6)), -1) BEGIN SELECT RAISE(ABORT,'VERSION-MONOTONIC-1: version regresses below the highest already deployed for this resource (issue #1451); add ROLLBACK-OK to notes for an intentional rollback.'); END;
